from __future__ import annotations


def generate_freecad_bobbin_script(
    flange_od_mm: float = 32.0,
    core_id_mm: float = 16.0,
    height_mm: float = 25.0,
    wall_thickness_mm: float = 1.5,
    output_step_path: str = "bobbin.step",
) -> str:
    """Generates a headless Python script for FreeCADCmd to generate a 3D transformer bobbin

    solid and export it to an ISO 10303 STEP file.
    """
    return f"""# FreeCADCmd Headless Bobbin Solid Generator
# Generated by Mendex Engineering Studio v1.5
import FreeCAD
import Part

doc = FreeCAD.newDocument("TransformerBobbin")

# Cylindrical barrel
outer_barrel = Part.makeCylinder({core_id_mm / 2.0 + wall_thickness_mm}, {height_mm})
inner_hole = Part.makeCylinder({core_id_mm / 2.0}, {height_mm})
barrel = outer_barrel.cut(inner_hole)

# Flanges
bottom_flange = Part.makeCylinder({flange_od_mm / 2.0}, {wall_thickness_mm})
bottom_flange_hole = Part.makeCylinder({core_id_mm / 2.0}, {wall_thickness_mm})
bottom = bottom_flange.cut(bottom_flange_hole)

top_flange = Part.makeCylinder({flange_od_mm / 2.0}, {wall_thickness_mm})
top_flange.translate(FreeCAD.Vector(0, 0, {height_mm - wall_thickness_mm}))
top_flange_hole = Part.makeCylinder({core_id_mm / 2.0}, {wall_thickness_mm})
top_flange_hole.translate(FreeCAD.Vector(0, 0, {height_mm - wall_thickness_mm}))
top = top_flange.cut(top_flange_hole)

# Fuse bobbin assembly
bobbin = barrel.fuse(bottom).fuse(top)
obj = doc.addObject("Part::Feature", "Bobbin")
obj.Shape = bobbin
doc.recompute()

# Export STEP
Part.export([obj], "{output_step_path}")
print("STEP export complete: {output_step_path}")
"""
